custom_css:
.sc-tw *,.sc-tw *::before,.sc-tw *::after{box-sizing:border-box;margin:0;padding:0}.sc-tw :root{
  --gold-bright: oklch(88% 0.14 85);
  --gold-mid: oklch(75% 0.16 80);
  --gold-warm: oklch(65% 0.18 75);
  --gold-deep: oklch(52% 0.15 72);
  --gold-root: oklch(38% 0.12 68);
  --amber-glow: oklch(82% 0.13 88);
  --cream-light: oklch(96% 0.05 90);
  --cream-mid: oklch(92% 0.08 88);
  --soil-dark: oklch(22% 0.06 65);
  --soil-mid: oklch(32% 0.08 70);
  --soil-surface: oklch(42% 0.1 72);
  --leaf-green: oklch(72% 0.14 145);
  --moon-silver: oklch(88% 0.03 100);
  --dew-glass: oklch(100% 0 0 / 0.1);
  --dew-border: oklch(100% 0 0 / 0.2);
  --dew-shine: oklch(100% 0 0 / 0.4);
  --bokeh-warm: oklch(92% 0.12 85 / 0.4);
  --font-display: 'Cormorant Garamond', Georgia, serif;
  --font-body: 'DM Sans', system-ui, sans-serif;
  --weight: 300;
}.sc-tw html{ scroll-behavior: smooth; overflow-x: hidden; }.sc-tw{
  font-family: var(--font-body);
  font-weight: 300;
  background: var(--soil-dark);
  color: var(--cream-light);
  min-height: 100vh;
  overflow-x: hidden;
  cursor: none;
}.sc-tw .cursor{
  position: fixed;
  width: 8px;
  height: 8px;
  background: var(--gold-bright);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
  mix-blend-mode: screen;
  transition: transform 0.1s ease;
}.sc-tw .cursor-aura{
  position: fixed;
  width: 36px;
  height: 36px;
  border: 1px solid oklch(88% 0.14 85 / 0.45);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9998;
  transform: translate(-50%, -50%);
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}.sc-tw body:has(button:hover) .cursor-aura,.sc-tw body:has(a:hover) .cursor-aura{
  width: 52px;
  height: 52px;
  border-color: var(--gold-warm);
  background: oklch(75% 0.16 80 / 0.06);
}.sc-tw .noise{
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 256px 256px;
}.sc-tw .bg-soil{
  position: fixed;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse 90% 70% at 50% 100%, oklch(38% 0.12 68 / 0.8) 0%, transparent 70%),
    radial-gradient(ellipse 60% 50% at 20% 50%, oklch(32% 0.1 75 / 0.5) 0%, transparent 60%),
    radial-gradient(ellipse 70% 60% at 80% 30%, oklch(28% 0.08 65 / 0.6) 0%, transparent 60%),
    oklch(18% 0.05 65);
}.sc-tw .light-corridor{
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80vw;
  height: 100vh;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle at center, oklch(92% 0.12 85 / 0.4) 0%, transparent 70%);
  backdrop-filter: blur(120px) saturate(1.5);
  -webkit-backdrop-filter: blur(120px) saturate(1.5);
  animation: corridor-breathe 12s ease-in-out infinite;
}

@keyframes corridor-breathe {0%,100%{opacity:0.8;transform:translateX(-50%) scaleY(1)}50%{opacity:1;transform:translateX(-50%) scaleY(1.05)}
}.sc-tw .dust-canvas{
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}.sc-tw nav{
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem clamp(2rem, 6vw, 5rem);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: oklch(18% 0.05 65 / 0.5);
  backdrop-filter: blur(60px) saturate(1.4);
  border-bottom: 1px solid oklch(88% 0.14 85 / 0.08);
}.sc-tw .nav-brand{
  display: flex;
  align-items: center;
  gap: 0.875rem;
  text-decoration: none;
}.sc-tw .nav-glyph{
  width: 32px;
  height: 32px;
  position: relative;
  flex-shrink: 0;
}.sc-tw .nav-glyph svg{
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 8px oklch(88% 0.14 85 / 0.6));
}.sc-tw .nav-wordmark{
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--cream-light);
}.sc-tw .nav-tagline{
  font-size: 0.6rem;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--gold-mid);
  margin-top: 0.1rem;
}.sc-tw .nav-links{
  display: flex;
  gap: 2.5rem;
  list-style: none;
}.sc-tw .nav-links a{
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: oklch(88% 0.05 90 / 0.7);
  text-decoration: none;
  transition: color 0.4s ease;
  font-weight: 400;
}.sc-tw .nav-links a:hover{ color: var(--gold-bright); }.sc-tw .btn-dew{
  position: relative;
  padding: 0.65rem 1.75rem;
  background: var(--dew-glass);
  border: 1px solid var(--dew-border);
  border-radius: 100px;
  color: var(--cream-light);
  font-family: var(--font-body);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: none;
  backdrop-filter: blur(20px) saturate(1.3);
  overflow: hidden;
  transition: all 0.45s cubic-bezier(0.16, 1, 0.3, 1);
  font-weight: 400;
}.sc-tw .btn-dew::before{
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 50%;
  background: linear-gradient(180deg, var(--dew-shine) 0%, transparent 100%);
  border-radius: 100px 100px 0 0;
  pointer-events: none;
}.sc-tw .btn-dew::after{
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
    oklch(92% 0.12 85 / 0.25) 0%, transparent 55%);
  opacity: 0;
  transition: opacity 0.35s ease;
  border-radius: 100px;
}.sc-tw .btn-dew:hover::after{ opacity: 1; }.sc-tw .btn-dew:hover{
  border-color: oklch(88% 0.14 85 / 0.4);
  box-shadow: 0 8px 40px oklch(75% 0.16 80 / 0.2), inset 0 0 20px oklch(92% 0.12 85 / 0.08);
}.sc-tw .btn-dew-gold{
  background: oklch(75% 0.16 80 / 0.2);
  border-color: oklch(88% 0.14 85 / 0.35);
  color: var(--gold-bright);
}.sc-tw .btn-dew-gold:hover{
  background: oklch(75% 0.16 80 / 0.32);
  box-shadow: 0 8px 50px oklch(75% 0.16 80 / 0.3), inset 0 0 30px oklch(92% 0.12 85 / 0.12);
}.sc-tw .scene{
  position: relative;
  z-index: 10;
  padding: 0 clamp(2rem, 6vw, 5rem);
}.sc-tw .hero{
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: clamp(6rem, 14vh, 10rem);
  padding-bottom: 4rem;
  position: relative;
}.sc-tw .hero-flow{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}.sc-tw .hero-text-column{
  position: relative;
}.sc-tw .eyebrow{
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 2rem;
  opacity: 0;
  animation: petal-unfold 1s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
}.sc-tw .eyebrow-leaf{
  width: 24px;
  height: 1px;
  background: linear-gradient(90deg, var(--gold-warm), transparent);
}.sc-tw .eyebrow-text{
  font-size: 0.65rem;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--gold-mid);
  font-weight: 500;
}.sc-tw .hero-title{
  font-family: var(--font-display);
  font-size: clamp(3.2rem, 7vw, 6.5rem);
  font-weight: 300;
  letter-spacing: -0.025em;
  line-height: 0.92;
  margin-bottom: 1.75rem;
  color: var(--cream-light);
}.sc-tw .hero-title-line{
  display: block;
  overflow: hidden;
}.sc-tw .hero-title-line span{
  display: inline-block;
  opacity: 0;
  transform: translateY(110%) rotate(2deg);
  animation: petal-rise 1.1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}.sc-tw .hero-title-line:nth-child(1) span{ animation-delay: 0.5s; }.sc-tw .hero-title-line:nth-child(2) span{ animation-delay: 0.68s; }.sc-tw .hero-title-line:nth-child(3) span{ animation-delay: 0.86s; }.sc-tw .hero-title .italic{
  font-style: italic;
  color: var(--gold-bright);
  font-weight: 300;
}.sc-tw .hero-subtitle{
  font-size: clamp(0.85rem, 1.1vw, 1rem);
  color: oklch(88% 0.05 90 / 0.65);
  line-height: 1.75;
  max-width: 42ch;
  margin-bottom: 2.5rem;
  font-weight: 300;
  opacity: 0;
  animation: petal-unfold 0.9s cubic-bezier(0.16, 1, 0.3, 1) 1.2s forwards;
}.sc-tw .hero-actions{
  display: flex;
  gap: 1rem;
  align-items: center;
  opacity: 0;
  animation: petal-unfold 0.9s cubic-bezier(0.16, 1, 0.3, 1) 1.4s forwards;
}.sc-tw .lunar-portal-wrap{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  animation: petal-unfold 1.2s cubic-bezier(0.16, 1, 0.3, 1) 0.6s forwards;
}.sc-tw .lunar-portal{
  position: relative;
  width: clamp(300px, 42vw, 560px);
  aspect-ratio: 4 / 5;
  border-radius: 60% 40% 55% 45% / 50% 55% 45% 50%;
  overflow: hidden;
  mask-image: radial-gradient(ellipse 85% 88% at 50% 50%, black 40%, transparent 100%);
  -webkit-mask-image: radial-gradient(ellipse 85% 88% at 50% 50%, black 40%, transparent 100%);
  animation: portal-morph 20s ease-in-out infinite;
}

@keyframes portal-morph {0%,100%{border-radius:60% 40% 55% 45% / 50% 55% 45% 50%}25%{border-radius:50% 50% 45% 55% / 55% 45% 55% 45%}50%{border-radius:45% 55% 60% 40% / 45% 55% 50% 50%}75%{border-radius:55% 45% 50% 50% / 50% 50% 45% 55%}
}.sc-tw .lunar-portal-video{
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(1.3) brightness(0.9) sepia(0.2);
}.sc-tw .lunar-portal-fallback{
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 70% at 50% 30%, oklch(88% 0.14 85 / 0.8) 0%, oklch(75% 0.16 80 / 0.5) 30%, transparent 70%),
    radial-gradient(ellipse 80% 60% at 30% 80%, oklch(52% 0.15 72 / 0.8) 0%, oklch(38% 0.12 68 / 0.6) 50%, transparent 80%),
    radial-gradient(ellipse 50% 50% at 70% 60%, oklch(72% 0.14 145 / 0.3) 0%, transparent 60%),
    oklch(28% 0.08 68);
  animation: harvest-shimmer 10s ease-in-out infinite;
}

@keyframes harvest-shimmer {0%,100%{filter:brightness(0.9) hue-rotate(0deg)}50%{filter:brightness(1.08) hue-rotate(8deg)}
}.sc-tw .lunar-portal-glow{
  position: absolute;
  inset: -20%;
  border-radius: inherit;
  background: radial-gradient(ellipse at center,
    oklch(88% 0.14 85 / 0.25) 0%,
    oklch(75% 0.16 80 / 0.1) 50%,
    transparent 80%);
  filter: blur(40px);
  z-index: -1;
  animation: portal-morph 20s ease-in-out infinite;
}.sc-tw .portal-overlay{
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 40% 40% at 50% 25%, oklch(96% 0.05 90 / 0.15) 0%, transparent 70%),
    linear-gradient(180deg, transparent 50%, oklch(18% 0.05 65 / 0.6) 100%);
  pointer-events: none;
}.sc-tw .moon-badge{
  position: absolute;
  top: 12%;
  right: -5%;
  width: 80px;
  height: 80px;
  background: oklch(88% 0.03 100 / 0.15);
  backdrop-filter: blur(20px);
  border: 1px solid oklch(88% 0.03 100 / 0.25);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 0.2rem;
  animation: badge-float 6s ease-in-out infinite;
}

@keyframes badge-float {0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-8px) rotate(3deg)}
}.sc-tw .moon-badge-val{
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--moon-silver);
  letter-spacing: -0.03em;
  line-height: 1;
}.sc-tw .moon-badge-label{
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: oklch(88% 0.03 100 / 0.7);
  text-align: center;
}.sc-tw .stats-river{
  display: flex;
  gap: 0;
  margin-top: clamp(3rem, 8vh, 6rem);
  position: relative;
}.sc-tw .stats-river::before{
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg,
    transparent,
    oklch(88% 0.14 85 / 0.3) 20%,
    oklch(88% 0.14 85 / 0.15) 80%,
    transparent);
}.sc-tw .stat-pod{
  flex: 1;
  padding: 2rem 2rem 2rem 0;
  border-right: 1px solid oklch(88% 0.14 85 / 0.08);
  margin-right: 2rem;
}.sc-tw .stat-pod:last-child{ border-right: none; }.sc-tw .stat-num{
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.5vw, 3rem);
  font-weight: 300;
  letter-spacing: -0.05em;
  color: var(--cream-light);
  line-height: 1;
  margin-bottom: 0.4rem;
}.sc-tw .stat-num .unit{
  font-size: 0.5em;
  color: var(--gold-mid);
  vertical-align: super;
  font-weight: 400;
}.sc-tw .stat-label{
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: oklch(75% 0.05 85 / 0.55);
  line-height: 1.5;
}.sc-tw .rhizo-section{
  padding: clamp(5rem, 12vh, 10rem) 0;
  position: relative;
}.sc-tw .rhizo-flow{
  display: flex;
  flex-direction: column;
  gap: clamp(5rem, 10vh, 8rem);
}.sc-tw .rhizo-row{
  display: grid;
  align-items: start;
  position: relative;
}.sc-tw .rhizo-row.left{ grid-template-columns: 1fr 1.4fr; gap: 5rem; }.sc-tw .rhizo-row.right{ grid-template-columns: 1.4fr 1fr; gap: 5rem; }.sc-tw .rhizo-row.center{ grid-template-columns: 1fr 1fr 1fr; gap: 3rem; align-items: center; }.sc-tw .rhizo-connector{
  position: absolute;
  left: 50%;
  top: -4rem;
  width: 1px;
  height: 4rem;
  background: linear-gradient(180deg, transparent, oklch(88% 0.14 85 / 0.2));
  transform: translateX(-50%);
}.sc-tw .section-eyebrow{
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}.sc-tw .leaf-stem{
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, var(--gold-warm), transparent);
}.sc-tw .section-tag{
  font-size: 0.62rem;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: var(--gold-mid);
  font-weight: 500;
}.sc-tw .section-title{
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.5vw, 3.2rem);
  font-weight: 300;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--cream-light);
  margin-bottom: 1.25rem;
}.sc-tw .section-title .italic{
  font-style: italic;
  color: var(--gold-bright);
}.sc-tw .section-body{
  font-size: 0.875rem;
  color: oklch(88% 0.05 90 / 0.6);
  line-height: 1.8;
  font-weight: 300;
  max-width: 46ch;
}.sc-tw .amber-leak{
  width: 100%;
  height: 1px;
  background: radial-gradient(ellipse 60% 100% at 30% 50%,
    oklch(88% 0.14 85 / 0.35) 0%,
    oklch(75% 0.16 80 / 0.15) 50%,
    transparent 100%);
  margin: 0.5rem 0;
  position: relative;
}.sc-tw .amber-leak::after{
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 40%;
  height: 100%;
  background: linear-gradient(90deg, oklch(88% 0.14 85 / 0.5), transparent);
  filter: blur(4px);
}.sc-tw .bio-card{
  position: relative;
  padding: 2rem 2rem 2rem 2.25rem;
  background: oklch(28% 0.07 70 / 0.5);
  border: 1px solid oklch(88% 0.14 85 / 0.1);
  border-radius: 24px 8px 24px 8px;
  overflow: hidden;
  backdrop-filter: blur(40px) saturate(1.3);
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.5s ease;
  cursor: none;
}.sc-tw .bio-card::before{
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, oklch(92% 0.12 85 / 0.25) 40%, transparent);
}.sc-tw .bio-card::after{
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 40%;
  background: linear-gradient(180deg, var(--gold-warm), transparent);
  border-radius: 0 0 3px 3px;
}.sc-tw .bio-card:hover{
  transform: translateY(-6px) rotate(-0.5deg);
  box-shadow: 0 40px 80px oklch(15% 0.06 65 / 0.5), 0 0 0 1px oklch(88% 0.14 85 / 0.12);
}.sc-tw .bio-card-glow{
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
    oklch(92% 0.12 85 / 0.08) 0%, transparent 55%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}.sc-tw .bio-card:hover .bio-card-glow{ opacity: 1; }.sc-tw .bio-card-icon{
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: oklch(88% 0.14 85 / 0.1);
  border: 1px solid oklch(88% 0.14 85 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.2rem;
  color: var(--gold-bright);
}.sc-tw .bio-card-title{
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: -0.01em;
  color: var(--cream-light);
  margin-bottom: 0.6rem;
  line-height: 1.25;
}.sc-tw .bio-card-text{
  font-size: 0.78rem;
  color: oklch(80% 0.05 85 / 0.55);
  line-height: 1.75;
  font-weight: 300;
}.sc-tw .metric-row{
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 1px solid oklch(88% 0.14 85 / 0.08);
}.sc-tw .metric-val{
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 300;
  letter-spacing: -0.04em;
  color: var(--gold-bright);
  line-height: 1;
}.sc-tw .metric-label{
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: oklch(75% 0.05 85 / 0.5);
  line-height: 1.4;
}.sc-tw .progress-vine{
  width: 100%;
  height: 2px;
  background: oklch(40% 0.08 70 / 0.4);
  border-radius: 1px;
  margin-top: 0.5rem;
  overflow: hidden;
  position: relative;
}.sc-tw .progress-vine-fill{
  height: 100%;
  background: linear-gradient(90deg, var(--gold-warm), var(--gold-bright));
  border-radius: 1px;
  transition: width 1.8s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
}.sc-tw .progress-vine-fill::after{
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold-bright);
  box-shadow: 0 0 8px var(--gold-warm);
}.sc-tw .circadian-display{
  background: oklch(22% 0.06 65 / 0.7);
  border: 1px solid oklch(88% 0.14 85 / 0.12);
  border-radius: 28px;
  padding: 2.5rem;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(60px);
}.sc-tw .circadian-ring{
  position: relative;
  width: 160px;
  height: 160px;
  margin: 0 auto 2rem;
}.sc-tw .circadian-ring svg{
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  filter: drop-shadow(0 0 12px oklch(88% 0.14 85 / 0.4));
}.sc-tw .circadian-ring-center{
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 0.25rem;
}.sc-tw .circadian-ring-val{
  font-family: var(--font-display);
  font-size: 2.2rem;
  font-weight: 300;
